"""Guard admin analytics dashboard shell."""

ANALYTICS_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Guard Analytics</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#17202a;background:#f3f6f8;line-height:1.4}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1180px;margin:auto;padding:28px 18px 60px}h1,h2,p{margin:0}.muted{color:#6d7b86;font-size:.86rem}.top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.badge{display:inline-flex;align-items:center;padding:6px 11px;border-radius:999px;background:#e4f6ec;color:#176b43;font-size:.78rem;font-weight:700}.filters{display:flex;gap:8px;flex-wrap:wrap;padding:12px;background:#fff;border:1px solid #dbe3e8;border-radius:14px;margin-bottom:18px}.filters select,.filters button{font:inherit;padding:8px 10px;border:1px solid #cbd5dc;border-radius:8px;background:#fff}.filters .primary{background:#1768cf;color:#fff;border-color:#1768cf}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.card,.panel{background:#fff;border:1px solid #dbe3e8;border-radius:14px;box-shadow:0 2px 8px #1b34400b}.card{padding:16px}.card strong{display:block;font-size:1.8rem}.card span{font-size:.8rem;color:#6d7b86}.panel{padding:18px;margin-top:18px}.panel h2{font-size:1.05rem;margin-bottom:12px}.table{width:100%;border-collapse:collapse;font-size:.86rem}.table th,.table td{text-align:left;padding:10px 8px;border-bottom:1px solid #edf0f2;vertical-align:top}.status{font-weight:700}.protected{color:#16834d}.attention{color:#b45b00}.incomplete{color:#c23b3b}.chart{height:190px;display:flex;align-items:end;gap:8px;padding:12px 4px;border-bottom:1px solid #dbe3e8;overflow-x:auto}.bar{min-width:18px;background:#2a78d0;border-radius:5px 5px 0 0;position:relative;cursor:default}.bar.attention{background:#b45b00}.bar.incomplete{background:#c23b3b}.bar span{position:absolute;bottom:-24px;left:50%;transform:translateX(-50%);font-size:10px;color:#6d7b86;white-space:nowrap}.empty{padding:18px 0}.mono{font-family:ui-monospace,monospace;font-size:.76rem}.cost{color:#176b43;font-weight:700}.tabs{display:flex;gap:4px;margin-bottom:12px}.tab{padding:6px 12px;border:1px solid #cbd5dc;border-radius:8px;background:#fff;cursor:pointer;font:inherit;font-size:.84rem}.tab.active{background:#1768cf;color:#fff;border-color:#1768cf}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.table{display:block;overflow-x:auto;white-space:nowrap}}
</style></head><body><main class="wrap">
<header class="top"><div><h1>Guard Analytics</h1><p class="muted">Daily safety reporting and AI cost tracking</p></div><span class="badge">Admin</span></header>
<form class="filters" onsubmit="load(event)"><select id="period"><option value="7d">Last 7 days</option><option value="24h">Last 24h</option><option value="30d">Last 30 days</option></select><button class="primary">Apply</button><button type="button" onclick="load()">Refresh</button></form>
<section id="cards" class="grid"></section>
<section class="panel"><h2>Daily volume</h2><div id="chart" class="chart"></div></section>
<section class="panel"><h2>Children</h2><div id="children" class="empty muted">Loading…</div></section>
<section class="panel"><h2>LLM Costs</h2><div class="tabs"><button class="tab active" data-group="model" onclick="switchTab('model')">By model</button><button class="tab" data-group="operation" onclick="switchTab('operation')">By operation</button><button class="tab" data-group="child" onclick="switchTab('child')">By child</button></div><div id="costs" class="empty muted">Loading…</div></section>
</main><script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&','<':'<','>':'>','"':'"',"'":'&#39;'}[c]));
let currentGroup='model';
async function load(e){e?.preventDefault();try{const period=document.getElementById('period').value;const[ov,ch,dl]=await Promise.all([fetch('/admin/api/guard/analytics/overview?period='+period).then(r=>r.json()),fetch('/admin/api/guard/analytics/children?period='+period).then(r=>r.json()),fetch('/admin/api/guard/analytics/daily?period='+period).then(r=>r.json())]);renderOverview(ov);renderChildren(ch);renderChart(dl);await loadCosts()}catch(err){document.body.innerHTML='<main class="wrap"><h1>Unable to load</h1><p class="muted">'+esc(err.message)+'</p></main>'}}
function renderOverview(o){document.getElementById('cards').innerHTML=[['Children monitored',o.children_monitored],['Messages',o.total_messages],['Assessments',o.total_assessments],['Security detections',o.total_security_detections],['Exposure detections',o.total_exposure_detections],['Security alerts sent',o.total_security_alerts_sent],['Exposure alerts sent',o.total_exposure_alerts_sent],['Coverage health',o.coverage_health_pct.toFixed(1)+'%']].map(([l,v])=>'<div class="card"><strong>'+esc(v)+'</strong><span>'+l+'</span></div>').join('')}
function renderChildren(rows){if(!rows.length){document.getElementById('children').innerHTML='<div class="empty muted">No data for this period.</div>';return}document.getElementById('children').innerHTML='<table class="table"><thead><tr><th>Date</th><th>Child</th><th>Status</th><th>Messages</th><th>Assessments</th><th>Detections</th><th>Alerts</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.local_date)+'</td><td>'+esc(r.child_name||r.child_user_id.slice(0,8))+'</td><td class="status '+r.coverage_status+'">'+r.coverage_status+'</td><td>'+r.messages_received+'</td><td>'+r.guard_assessments+'</td><td>'+(r.security_detections+r.exposure_detections)+'</td><td>'+(r.security_alerts_sent+r.exposure_alerts_sent)+'</td></tr>').join('')+'</tbody></table>'}
function renderChart(series){if(!series.length){document.getElementById('chart').innerHTML='<div class="empty muted">No data.</div>';return}const max=Math.max(1,...series.map(s=>s.messages_received));document.getElementById('chart').innerHTML=series.map(s=>'<div class="bar" title="'+s.local_date+': '+s.messages_received+' msgs, '+(s.security_detections+s.exposure_detections)+' detections" style="height:'+Math.max(8,Math.round(s.messages_received/max*150))+'px"><span>'+s.local_date.slice(5)+'<br>'+s.messages_received+'</span></div>').join('')}
async function loadCosts(){try{const period=document.getElementById('period').value;const r=await fetch('/admin/api/guard/analytics/costs?period='+period+'&group_by='+currentGroup);const d=await r.json();renderCosts(d)}catch(e){document.getElementById('costs').innerHTML='<div class="empty muted">No cost data.</div>'}}
function renderCosts(d){const o=d.overview;const groups=d.groups||[];let html='<div class="grid" style="grid-template-columns:repeat(3,1fr);margin-bottom:14px"><div class="card"><strong class="cost">$'+(o.total_cost_usd||0).toFixed(4)+'</strong><span>Total cost</span></div><div class="card"><strong>'+o.total_events+'</strong><span>Events ('+o.error_events+' errors)</span></div><div class="card"><strong>'+o.instrumentation_coverage_pct.toFixed(1)+'%</strong><span>Instrumentation coverage</span></div></div>';html+='<table class="table"><thead><tr><th>'+(currentGroup==='model'?'Model':currentGroup==='operation'?'Operation':'Child')+'</th><th>Events</th><th>Prompt tokens</th><th>Completion tokens</th><th>Cost</th></tr></thead><tbody>';for(const g of groups){html+='<tr><td class="mono">'+esc(g.key)+'</td><td>'+g.events+'</td><td>'+(g.prompt_tokens||0).toLocaleString()+'</td><td>'+(g.completion_tokens||0).toLocaleString()+'</td><td class="cost">$'+(g.cost_usd||0).toFixed(6)+'</td></tr>'}if(!groups.length)html+='<tr><td colspan="5" class="muted">No data.</td></tr>';html+='</tbody></table>';document.getElementById('costs').innerHTML=html}
function switchTab(g){currentGroup=g;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.group===g));loadCosts()}
load();setInterval(load,60000);
</script></body></html>'''
